Save this as `lambda.py`:

```python
import json
import logging
import boto3
from datetime import datetime, timezone

logger = logging.getLogger()
logger.setLevel(logging.INFO)

iam = boto3.client("iam")


def lambda_handler(event, context):
    findings = []

    paginator = iam.get_paginator("list_users")

    for page in paginator.paginate():
        for user in page["Users"]:
            username = user["UserName"]

            keys = iam.list_access_keys(UserName=username)["AccessKeyMetadata"]

            for key in keys:
                last_used = iam.get_access_key_last_used(
                    AccessKeyId=key["AccessKeyId"]
                ).get("AccessKeyLastUsed", {})

                findings.append({
                    "user": username,
                    "access_key_id": key["AccessKeyId"],
                    "status": key["Status"],
                    "created": key["CreateDate"].isoformat(),
                    "last_used": (
                        last_used.get("LastUsedDate").isoformat()
                        if last_used.get("LastUsedDate")
                        else None
                    ),
                    "region": last_used.get("Region"),
                    "service": last_used.get("Service"),
                })

    report = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "access_keys": findings,
    }

    # Deliberately logs metadata only; secret access keys are never retrieved.
    logger.info(json.dumps(report, default=str))

    return {
        "statusCode": 200,
        "key_count": len(findings),
    }
```

