Safe, offline demonstration of the AWS iam:PassRole + Lambda privilege
escalation pattern.

This script does not contact AWS, create Lambda functions, assume roles,
or execute code. It only evaluates example policies and prints why the
combination is dangerous.
"""

from fnmatch import fnmatch


# A deliberately risky identity policy assigned to "developer".
developer_policy = {
    "Version": "2012-10-17",
    "Statement": [
        {
            "Sid": "LambdaDeployment",
            "Effect": "Allow",
            "Action": [
                "lambda:CreateFunction",
                "lambda:UpdateFunctionCode",
                "lambda:InvokeFunction"
            ],
            "Resource": "*"
        },
        {
            "Sid": "PassExecutionRoles",
            "Effect": "Allow",
            "Action": "iam:PassRole",
            "Resource": "*"
        }
    ]
}

# Example role that the developer could pass to a Lambda function.
lambda_execution_role = {
    "RoleName": "analytics-lambda-role",
    "Arn": "arn:aws:iam::111122223333:role/analytics-lambda-role",
    "AttachedPermissions": [
        "s3:GetObject",
        "dynamodb:*",
        "secretsmanager:GetSecretValue"
    ]
}


def as_list(value):
    if isinstance(value, list):
        return value
    return [value]


def action_allowed(policy, wanted_action):
    for statement in policy.get("Statement", []):
        if statement.get("Effect") != "Allow":
            continue

        actions = as_list(statement.get("Action", []))
        if any(fnmatch(wanted_action.lower(), a.lower()) for a in actions):
            return True

    return False


def resource_scope(policy, wanted_action):
    scopes = []

    for statement in policy.get("Statement", []):
        if statement.get("Effect") != "Allow":
            continue

        actions = as_list(statement.get("Action", []))
        if any(fnmatch(wanted_action.lower(), a.lower()) for a in actions):
            scopes.extend(as_list(statement.get("Resource", "*")))

    return scopes


def analyze():
    can_create_lambda = action_allowed(
        developer_policy, "lambda:CreateFunction"
    )
    can_pass_role = action_allowed(
        developer_policy, "iam:PassRole"
    )

    if not can_create_lambda or not can_pass_role:
        print("[+] No dangerous permission combination detected.")
        return

    lambda_scope = resource_scope(
        developer_policy, "lambda:CreateFunction"
    )
    passrole_scope = resource_scope(
        developer_policy, "iam:PassRole"
    )

    print("[!] Potential privilege-escalation path detected\n")

    print("Identity: developer")
    print(f"  lambda:CreateFunction scope: {lambda_scope}")
    print(f"  iam:PassRole scope:          {passrole_scope}")

    print("\nTarget role:")
    print(f"  {lambda_execution_role['RoleName']}")
    print(f"  {lambda_execution_role['Arn']}")
    print("  Permissions:")
    for permission in lambda_execution_role["AttachedPermissions"]:
