    print("  1. The principal can create or update a Lambda function.")
    print("  2. The principal can pass an IAM role to that function.")
    print("  3. The role grants permissions beyond the principal's intended scope.")
    print("  4. Code running in the Lambda environment would inherit that role.")

    print("\nRisk:")
    print("  A principal with this combination may be able to cause code")
    print("  to run under the permissions of the passed execution role.")

    print("\nRecommended controls:")
    print("  - Scope iam:PassRole to approved role ARNs.")
    print("  - Add iam:PassedToService = lambda.amazonaws.com.")
    print("  - Restrict Lambda creation to approved function names or paths.")
    print("  - Avoid wildcard permissions such as Resource: '*'.")
    print("  - Monitor CreateFunction, UpdateFunctionCode, and PassRole events.")


if __name__ == "__main__":
