#!/usr/bin/env python3
"""
Read-only IAM escalation-risk audit.

Usage:
    python3 iam_escalation_audit.py USERNAME
"""

import json
import sys
import boto3
from botocore.exceptions import ClientError

RISKY_ACTIONS = {
    "iam:CreatePolicyVersion",
    "iam:SetDefaultPolicyVersion",
    "iam:AttachUserPolicy",
    "iam:AttachRolePolicy",
    "iam:PutUserPolicy",
    "iam:PutRolePolicy",
    "iam:UpdateAssumeRolePolicy",
    "iam:PassRole",
    "sts:AssumeRole",
}

iam = boto3.client("iam")


def action_matches(action, target):
    action = action.lower()
    target = target.lower()
    return action in ("*", target, target.split(":")[0] + ":*")


def statements_from_document(document):
    if isinstance(document, str):
        document = json.loads(document)

    statements = document.get("Statement", [])
    return statements if isinstance(statements, list) else [statements]


def extract_actions(statement):
    actions = statement.get("Action", [])
    if isinstance(actions, str):
        actions = [actions]
    return actions


def inspect_policy(policy_name, document, source):
    findings = []

    for statement in statements_from_document(document):
        if statement.get("Effect", "").lower() != "allow":
            continue

        actions = extract_actions(statement)
        resources = statement.get("Resource", "*")

        for action in actions:
            for risky in RISKY_ACTIONS:
                if action_matches(action, risky):
                    findings.append({
                        "source": source,
                        "policy": policy_name,
                        "action": action,
                        "resource": resources,
                        "condition": statement.get("Condition", {})
                    })

    return findings


def get_managed_policy_document(policy_arn):
    meta = iam.get_policy(PolicyArn=policy_arn)["Policy"]
    version_id = meta["DefaultVersionId"]

    version = iam.get_policy_version(
        PolicyArn=policy_arn,
        VersionId=version_id
    )

    return version["PolicyVersion"]["Document"]


def audit_user(username):
    findings = []

    # Inline user policies
    paginator = iam.get_paginator("list_user_policies")
    for page in paginator.paginate(UserName=username):
        for policy_name in page["PolicyNames"]:
            response = iam.get_user_policy(
                UserName=username,
                PolicyName=policy_name
            )
            findings.extend(
                inspect_policy(
                    policy_name,
                    response["PolicyDocument"],
                    "user-inline"
                )
            )

    # Managed policies directly attached to user
    paginator = iam.get_paginator("list_attached_user_policies")
    for page in paginator.paginate(UserName=username):
        for policy in page["AttachedPolicies"]:
            document = get_managed_policy_document(policy["PolicyArn"])
            findings.extend(
                inspect_policy(
                    policy["PolicyName"],
                    document,
                    "user-managed"
                )
            )

    # Policies inherited through groups
    group_paginator = iam.get_paginator("list_groups_for_user")
    for page in group_paginator.paginate(UserName=username):
        for group in page["Groups"]:
            group_name = group["GroupName"]

            inline_paginator = iam.get_paginator("list_group_policies")
            for inline_page in inline_paginator.paginate(GroupName=group_name):
                for policy_name in inline_page["PolicyNames"]:
                    response = iam.get_group_policy(
                        GroupName=group_name,
                        PolicyName=policy_name
                    )
                    findings.extend(
                        inspect_policy(
                            policy_name,
                            response["PolicyDocument"],
                            f"group-inline:{group_name}"
                        )
                    )

            attached_paginator = iam.get_paginator(
                "list_attached_group_policies"
            )
            for attached_page in attached_paginator.paginate(
                GroupName=group_name
            ):
                for policy in attached_page["AttachedPolicies"]:
                    document = get_managed_policy_document(
                        policy["PolicyArn"]
                    )
                    findings.extend(
                        inspect_policy(
                            policy["PolicyName"],
                            document,
                            f"group-managed:{group_name}"
                        )
                    )

    return findings


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} USERNAME", file=sys.stderr)
        sys.exit(2)

    username = sys.argv[1]

    try:
        findings = audit_user(username)
    except ClientError as exc:
        print(f"AWS error: {exc}", file=sys.stderr)
        sys.exit(1)

    if not findings:
        print("No directly attached or group-inherited risky permissions found.")
        return

    print(json.dumps({
        "user": username,
        "risk": "Potential IAM privilege-escalation exposure",
        "findings": findings
    }, indent=2, default=str))


if __name__ == "__main__":
    main()
```

