```python
#!/usr/bin/env python3
"""
Read-only IAM trust-policy audit for potential AWS Confused Deputy issues.

Requirements:
    pip install boto3

Permissions:
    iam:ListRoles
    iam:GetRole
"""

import json
import re
import boto3
from botocore.exceptions import ClientError

ACCOUNT_ID_RE = re.compile(r"^\d{12}$")


def as_list(value):
    if value is None:
        return []
    return value if isinstance(value, list) else [value]


def get_condition_values(condition, key_names):
    values = []
    for key in key_names:
        if key in condition:
            values.extend(as_list(condition[key]))
    return values


def audit_statement(statement, role_name):
    findings = []

    if statement.get("Effect") != "Allow":
        return findings

    actions = as_list(statement.get("Action"))
    if not any(a in ("sts:AssumeRole", "*") for a in actions):
        return findings

    principal = statement.get("Principal", {})
    condition = statement.get("Condition", {})

    # Wildcard principal
    if principal == "*" or principal.get("AWS") == "*":
        findings.append({
            "severity": "HIGH",
            "role": role_name,
            "issue": "Trust policy allows any AWS principal",
            "statement": statement,
        })

    # AWS account/user/role principals
    aws_principals = as_list(principal.get("AWS"))
    for p in aws_principals:
        if isinstance(p, str):
            account_id = p.split(":")[4] if p.startswith("arn:aws:iam::") else p

            if ACCOUNT_ID_RE.match(account_id):
                external_id = get_condition_values(
                    condition,
                    ["sts:ExternalId", "sts:ExternalID"]
                )

                if not external_id:
                    findings.append({
                        "severity": "HIGH",
                        "role": role_name,
                        "issue": (
                            "Cross-account AWS principal can assume the role "
                            "without an sts:ExternalId condition"
                        ),
                        "principal": p,
                        "statement": statement,
                    })

    # Service principals
    service_principals = as_list(principal.get("Service"))
    if service_principals:
        has_source_restriction = any(
            key in condition
            for key in (
                "aws:SourceArn",
                "aws:SourceAccount",
                "ArnLike",
                "ArnEquals",
            )
        )

        if not has_source_restriction:
            findings.append({
                "severity": "MEDIUM",
                "role": role_name,
                "issue": (
                    "Service principal trust lacks aws:SourceArn or "
                    "aws:SourceAccount restriction"
                ),
                "service_principal": service_principals,
                "statement": statement,
            })

    return findings


def main():
    iam = boto3.client("iam")
    findings = []

    paginator = iam.get_paginator("list_roles")

    for page in paginator.paginate():
        for role in page["Roles"]:
            role_name = role["RoleName"]

            try:
                response = iam.get_role(RoleName=role_name)
                trust_policy = response["Role"]["AssumeRolePolicyDocument"]

                if isinstance(trust_policy, str):
                    trust_policy = json.loads(trust_policy)

                for statement in as_list(trust_policy.get("Statement")):
                    if isinstance(statement, dict):
                        findings.extend(
                            audit_statement(statement, role_name)
                        )

            except ClientError as exc:
                print(f"[WARN] Could not inspect {role_name}: {exc}")

    print(json.dumps(findings, indent=2, default=str))

    print(f"\nFound {len(findings)} potential finding(s).")


if __name__ == "__main__":
    main()
```

