### `policy.ts`

Run this policy pack independently of the deployment code so that changing the application program or state does not disable the controls.

```typescript
import * as policy from "@pulumi/policy";

const production = process.env.PULUMI_STACK === "prod";

const approvedTypes = new Set([
    "aws:cloudwatch/logGroup:LogGroup",
    "aws:iam/role:Role",
]);

const requiredTags = ["Owner", "Application", "Environment", "ManagedBy"];

new policy.PolicyPack("production-state-integrity", {
    policies: [
        {
            name: "approved-resource-types",
            description: "Production may only contain explicitly approved resource types.",
            enforcementLevel: "mandatory",
            validateResource: (args, reportViolation) => {
                if (production && !approvedTypes.has(args.resourceType)) {
                    reportViolation(
                        `Resource type ${args.resourceType} is not approved for production.`,
                    );
                }
            },
        },
        {
            name: "required-resource-tags",
            description: "Resources must have ownership and management metadata.",
            enforcementLevel: "mandatory",
            validateResource: (args, reportViolation) => {
                const props = args.props as Record<string, unknown>;
                const tags = (props.tags ?? {}) as Record<string, string>;

                for (const tag of requiredTags) {
                    if (!tags[tag]) {
                        reportViolation(
                            `${args.name} is missing required tag '${tag}'.`,
                        );
                    }
                }
            },
        },
        {
            name: "deny-production-iam-policy-attachments",
            description: "Prevent unexpected IAM policy attachments in production.",
            enforcementLevel: "mandatory",
            validateResource: (args, reportViolation) => {
                const blockedTypes = new Set([
                    "aws:iam/rolePolicyAttachment:RolePolicyAttachment",
                    "aws:iam/userPolicyAttachment:UserPolicyAttachment",
                    "aws:iam/groupPolicyAttachment:GroupPolicyAttachment",
                ]);

                if (production && blockedTypes.has(args.resourceType)) {
                    reportViolation(
                        `IAM policy attachment ${args.name} is prohibited in production.`,
                    );
                }
            },
        },
    ],
});
```

